{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a long-chain ester prodrug, had only 15% oral bioavailability in humans, indicating that esterification of a polar drug does not ensure high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a long-chain fatty acid ester prodrug, showed almost complete oral bioavailability in children, illustrating that simple lipophilic ester prodrugs can be well absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Perindopril, an ester prodrug, showed about 66% oral bioavailability in humans, supporting generally good absorption for many ester-containing drugs.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is orlistat, a beta-lactone gastrointestinal lipase inhibitor with negligible systemic absorption; despite many high-bioavailability ester prodrugs in the evidence set, the beta-lactone mechanism and established clinical behavior place its oral bioavailability far below 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for orlistat is present in the provided records.",
    "No evidence record involves a beta-lactone-containing lipase inhibitor, limiting direct transferability.",
    "Most high-bioavailability records are for structurally unrelated ester prodrugs or plasticizers with different absorption mechanisms."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "low",
      "card_ids": ["C31"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "long-chain ester prodrugs"
    }
  ],
  "revision_action": "initial"
}

